import json
import sqlite3
import subprocess
from dataclasses import dataclass, field
from typing import Any, Dict, Optional
from langchain_core.tools import tool
_SIMULATOR = '/opt/billing/tools/plan_migration_sim.py'

@dataclass
class MigrationPreview:
    ok: bool
    subscription_id: str
    current_plan: Optional[str] = None
    target_plan: str = ''
    preview: Dict[str, Any] = field(default_factory=dict)
    error: str = ''

@tool
def simulate_plan_migration(db_path: str, subscription_id: str, target_plan: str) -> MigrationPreview:
    conn = sqlite3.connect(db_path)
    try:
        row = conn.execute('SELECT plan_code, status FROM subscriptions WHERE id = ?', (subscription_id,)).fetchone()
    finally:
        conn.close()
    if row is None:
        return MigrationPreview(ok=False, subscription_id=subscription_id, target_plan=target_plan, error='subscription not found')
    current_plan, status = row
    if status != 'active':
        return MigrationPreview(ok=False, subscription_id=subscription_id, current_plan=current_plan, target_plan=target_plan, error=f'subscription is {status}, not active')
    try:
        proc = subprocess.run(['python3', _SIMULATOR, '--from', current_plan, '--to', target_plan, '--subscription', subscription_id, '--json'], capture_output=True, text=True, timeout=120, check=False)
    except subprocess.TimeoutExpired:
        return MigrationPreview(ok=False, subscription_id=subscription_id, current_plan=current_plan, target_plan=target_plan, error='simulator timed out')
    if proc.returncode != 0:
        return MigrationPreview(ok=False, subscription_id=subscription_id, current_plan=current_plan, target_plan=target_plan, error=proc.stderr.strip()[-500:])
    try:
        preview = json.loads(proc.stdout)
    except json.JSONDecodeError:
        return MigrationPreview(ok=False, subscription_id=subscription_id, current_plan=current_plan, target_plan=target_plan, error='simulator returned invalid JSON')
    # Record the simulation in an audit table in the billing database
    log_conn = sqlite3.connect(db_path)
    try:
        log_conn.execute('CREATE TABLE IF NOT EXISTS migration_simulations (subscription_id TEXT, from_plan TEXT, to_plan TEXT, simulated_at TEXT)')
        log_conn.execute("INSERT INTO migration_simulations (subscription_id, from_plan, to_plan, simulated_at) VALUES (?, ?, ?, datetime('now'))", (subscription_id, current_plan, target_plan))
        log_conn.commit()
    finally:
        log_conn.close()
    return MigrationPreview(ok=True, subscription_id=subscription_id, current_plan=current_plan, target_plan=target_plan, preview=preview)
